mapper.select:
SELECT
d.*,
si.name as stationName
FROM debt_expand d
LEFT JOIN station_info si ON d.station_id = si.id AND si.deleted = 0

WHERE d.deleted = 0


    AND d.station_id = #{pageReqVO.stationId}


    AND si.name LIKE CONCAT('%', #{pageReqVO.stationName}, '%')


    AND d.type = #{pageReqVO.type}


    AND d.range = #{pageReqVO.range}


    AND d.progress = #{pageReqVO.progress}


    AND d.status = #{pageReqVO.status}


    AND d.audit_time BETWEEN #{pageReqVO.auditTime[0]} AND #{pageReqVO.auditTime[1]}


    AND d.audit_user_id = #{pageReqVO.auditUserId}


    AND d.finish_time BETWEEN #{pageReqVO.finishTime[0]} AND #{pageReqVO.finishTime[1]}


    AND d.recovery_rate = #{pageReqVO.recoveryRate}


    AND d.remark = #{pageReqVO.remark}


    AND d.reserve1 = #{pageReqVO.reserve1}


    AND d.reserve2 = #{pageReqVO.reserve2}


    AND d.creator = #{pageReqVO.creator}


    AND d.updater = #{pageReqVO.updater}


    AND d.create_time >= #{pageReqVO.createTimeStart}


    AND d.create_time <= #{pageReqVO.createTimeEnd}


    AND d.update_time BETWEEN #{pageReqVO.updateTime[0]} AND #{pageReqVO.updateTime[1]}


ORDER BY d.id DESC
